package org.eclipse.rdf4j.sail.lucene;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.DynamicTest.dynamicTest;

import java.nio.file.Path;
import java.util.Arrays;
import java.util.stream.Stream;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryParseOptions;
import org.eclipse.rdf4j.query.QueryParseOptions.GraphAlgebraMode;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.evaluation.TupleFunctionEvaluationMode;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.TestFactory;
import org.junit.jupiter.api.io.TempDir;

class LuceneGraphAlgebraFallbackTest {

	@TempDir
	Path directory;

	@TestFactory
	Stream<DynamicTest> automaticModeStaysLegacyUntilSearchRewritesPreserveGraphScope() {
		return Arrays.stream(TupleFunctionEvaluationMode.values())
				.map(mode -> dynamicTest(mode.name(), () -> checkFallback(mode)));
	}

	private void checkFallback(TupleFunctionEvaluationMode mode) {
		LuceneSail sail = new LuceneSail();
		sail.setBaseSail(new MemoryStore());
		sail.setEvaluationMode(mode);
		sail.setParameter(LuceneSail.LUCENE_DIR_KEY, "index");
		sail.setParameter(LuceneSail.INDEX_CLASS_KEY, LuceneSail.DEFAULT_INDEX_CLASS);
		sail.setDataDir(directory.resolve(mode.name()).toFile());
		SailRepository repository = new SailRepository(sail);
		try (var connection = repository.getConnection()) {
			assertFalse(connection.getSailConnection().supportsGraphAlgebra());
			var vf = repository.getValueFactory();
			var subject = vf.createIRI("urn:subject");
			connection.add(subject, vf.createIRI("urn:text"), vf.createLiteral("needle"), vf.createIRI("urn:data"));
			String search = "PREFIX search: <http://www.openrdf.org/contrib/lucenesail#> "
					+ "SELECT ?s WHERE { ?s search:matches [search:query \"needle\"] }";
			var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, search, null);
			assertEquals(GraphAlgebraMode.LEGACY, query.getParsedQuery().getParseOptions().graphAlgebraMode());
			try (var rows = query.evaluate()) {
				assertTrue(rows.hasNext());
				assertEquals(subject, rows.next().getValue("s"));
				assertFalse(rows.hasNext());
			}

			String absent = "SELECT ?x WHERE { GRAPH <urn:missing> { BIND(1 AS ?x) } }";
			var automatic = connection.prepareTupleQuery(QueryLanguage.SPARQL, absent, null);
			assertEquals(GraphAlgebraMode.LEGACY, automatic.getParsedQuery().getParseOptions().graphAlgebraMode());
			try (var rows = automatic.evaluate()) {
				assertTrue(rows.hasNext(), "AUTO retains the documented historical GRAPH limitation");
				assertEquals("1", rows.next().getValue("x").stringValue());
				assertFalse(rows.hasNext());
			}

			// Explicit policy still overrides AUTO; this control has no search rewrite requiring Graph support.
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.GRAPH));
			var explicit = connection.prepareTupleQuery(QueryLanguage.SPARQL, absent, null);
			assertEquals(GraphAlgebraMode.GRAPH, explicit.getParsedQuery().getParseOptions().graphAlgebraMode());
			try (var rows = explicit.evaluate()) {
				assertFalse(rows.hasNext());
			}
		} finally {
			repository.shutDown();
		}
	}
}
